import sys, json, subprocess, importlib.util, os
sys.path.insert(0, "/tmp/cutharness")
OUT="/home/tirandagan.guest/naive-arm/output"
def load(name, path):
    spec=importlib.util.spec_from_file_location(name, path); m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
syn=load("cut", f"{OUT}/cut.py").cut_syntax_spec
io=load("io", f"{OUT}/annotation/InputOutputInfoGeneratorCut.py").InputOutputInfoGeneratorCut
par=load("par", f"{OUT}/annotation/ParallelizabilityInfoGeneratorCut.py").ParallelizabilityInfoGeneratorCut
table=json.load(open(f"{OUT}/annotation/cut.json"))

# --- consistency between syntax spec and json table
opts=syn[0][0]
spec_flags={s for n in opts if type(n).__name__=="Flag" for s in [n.flag]+n.alias}
spec_opts={s for n in opts if type(n).__name__!="Flag" for s in [n.flag]+n.alias}
json_flags={s for e in table["flag"] for s in ([e] if isinstance(e,str) else e)}
json_opts={s for e in table["option"] for s in e[:-1]}
assert spec_flags==json_flags, (spec_flags^json_flags)
assert spec_opts==json_opts, (spec_opts^json_opts)
# every spelling accepted by the binary and vice versa (from --help)
help_=subprocess.run(["/usr/bin/cut","--help"],capture_output=True,text=True).stdout
import re
help_spellings=set(re.findall(r"(?<![\w-])(--?[a-zA-Z][\w-]*)", help_)) - {"-"}
help_spellings -= {w for w in help_spellings if w.startswith("--") and w[2:] not in help_.replace("=", " ")}
print("spellings in --help not in spec:", help_spellings-(spec_flags|spec_opts))
print("spellings in spec not in --help:", (spec_flags|spec_opts)-help_spellings)

# --- PaSh-style parser
def parse(words):
    flags=[]; ops=[]; i=0
    while i<len(words):
        w=words[i]
        if w in json_flags: flags.append((w,)); i+=1; continue
        if w in json_opts: flags.append((w,words[i+1])); i+=2; continue
        if "=" in w and w.split("=",1)[0] in json_opts: flags.append(tuple(w.split("=",1))); i+=1; continue
        if len(w)>2 and w[0]=="-" and w[1]!="-" and all("-"+c in json_flags for c in w[1:]):
            flags+= [("-"+c,) for c in w[1:]]; i+=1; continue
        ops=words[i:]; break
    return flags, ops

os.chdir("/tmp/cuttest")
cases=[["-b1-3","in1"],["--bytes","1-3","in1"],["--bytes=1,3","in1"],["-d:","-f2","in1","in2"],["-d",":","-f","2"],
