for c in cases:
    flags,ops=parse(c)
    # Does the binary agree on which words are operands? Make each operand point to a nonexistent file and look at errors.
    probe=[w if w not in ops else "NOFILE_"+w for w in c]
    r=subprocess.run(["/usr/bin/cut"]+probe,capture_output=True,text=True,input="")
    binary_ops=re.findall(r"cut: (NOFILE_\S+): No such", r.stderr)
    ok = [("NOFILE_"+o) for o in ops]==binary_ops and "Try" not in r.stderr.replace("No such file","")
    g=io(flags,ops); g.generate_info()
    p=par(flags,ops); p.generate_info()
    # stdin usage check: run with real files, feeding stdin a marker line; marker should appear iff g.stdin
    r2=subprocess.run(["/usr/bin/cut"]+c,capture_output=True,text=True,input="STDINMARK:zz:zz\n")
    stdin_used = "STDINMARK" in r2.stdout or "zz" in r2.stdout and not ops
    print(f"{'OK ' if ok and stdin_used==g.stdin else 'BAD'} cut {' '.join(c):45} ops={ops} stdin={g.stdin} stdout={g.stdout} par={p.parallelizers}")
